// Parliamentary Procedure Practice Test 2. Original questions written for Valus from the HOSA 2026–27
// test plan (National Association of Parliamentarians topics), slightly harder than the sample items:
// applying Robert’s Rules to meeting situations, vote thresholds and motion characteristics.
import {q, mix} from './q.js';
const RONR='Robert’s Rules of Order Newly Revised', BRIEF='Robert’s Rules of Order Newly Revised In Brief';
const WHY='Why Have Rules', MEET='What Happens at a Meeting?', MOT='Handling Motions', DEB='Debate', AMD='Amendments', POST='Postponing and Referring to a Committee', MIND='How a Group Can Change Its Mind', VOTE='Voting and Elections', BYL='Bylaws and Other Rules and How to Use Them', ENF='How Rules are Enforced and Suspended', TABLE='Table of Rules', OFF='Officers, Committee Chairman, or Member';

export default {
 id:'parliamentary-procedure-2',
 event:'Parliamentary Procedure',
 title:'Practice Test 2',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Robert’s Rules of Order Newly Revised, RONR In Brief and NAP study questions',
 plan:[{area:'National Association of Parliamentarians',weight:100,topics:[WHY,MEET,MOT,DEB,AMD,POST,MIND,VOTE,BYL,ENF,TABLE,OFF]}],
 questions:mix([
  q(WHY,'Which phrase best summarizes the purpose of parliamentary procedure?','Majority rule while protecting minority rights',['Fast decisions made by the presiding officer','Unanimous agreement required on every question','Equal speaking time reserved for officers only'],'A','Robert’s Rules lets the majority decide after full and fair debate while guaranteeing the minority a chance to be heard.',BRIEF),
  q(WHY,'A meeting has fewer members present than the quorum. Which action may still be taken?','Adjourn, recess or take steps to obtain a quorum',['Adopt any main motion by a two-thirds vote','Elect officers as long as the ballot is secret','Amend the bylaws if previous notice was given'],'B','Without a quorum, the only actions allowed are those needed to end the meeting or obtain a quorum. Other business done anyway is null and void.',RONR),
  q(WHY,'An organization’s bylaws name Robert’s Rules as its parliamentary authority. When does RONR govern?','When it is consistent with the bylaws and special rules',['Only when the president specifically requests it','Whenever it conflicts with the organization’s bylaws','Only at the annual meeting of the full membership'],'C','The parliamentary authority applies in all cases where it is applicable and not inconsistent with the bylaws or special rules of order.',BRIEF),
  q(WHY,'What is a “deliberative assembly” under Robert’s Rules?','A group meeting to discuss and decide as one body',['Any group of people that has a written mission','A board appointed entirely by an outside authority','A committee that reports only to paid staff members'],'D','A deliberative assembly meets to discuss and decide questions as a group, where each member has one vote and members may differ in opinion.',RONR),
  q(MEET,'In the standard order of business, which heading comes immediately after reports of officers?','Reports of standing committees',['Unfinished business and general orders','New business','Special orders'],'A','The standard order is: minutes, officers’ reports, standing committee reports, special committee reports, special orders, unfinished business, new business.',BRIEF),
  q(MEET,'How are the minutes of the previous meeting usually approved?','By general consent after any corrections',['By a two-thirds rising vote of members','By a secret ballot vote of the members','By the secretary’s signature, without a vote'],'B','The chair asks for corrections, which are made, and then declares the minutes approved as read or as corrected by general consent.',BRIEF),
  q(MEET,'What is “unanimous (general) consent”?','Taking action when no member objects',['A vote in which every member votes yes','A vote taken later by mail ballot','A rule that needs every member’s signature'],'C','The chair asks if there is any objection. If none is heard, the action is taken without a formal vote; a single objection requires a vote.',RONR),
  q(MEET,'Two members seek the floor at the same time to debate a motion. Who generally gets preference?','The maker of the motion, if not yet heard',['The member who holds the senior office','The member who stood up and spoke louder','The member who will speak in its favor'],'D','The maker of the motion has the first right to speak on it. Otherwise preference goes to a member who has not yet spoken on the question.',RONR),
  q(MOT,'What are the three steps for bringing a motion before the assembly?','A member moves, another seconds, the chair states it',['Members debate it, vote on it and record it','A member seconds it, amends it and refers it','A member proposes it, tables it and adopts it'],'A','A motion is made by a member, seconded by another, and stated by the chair. Only then does it belong to the assembly for debate.',BRIEF),
  q(MOT,'A motion was never seconded, but debate has already begun when a member notices. What happens?','The motion stands, since the defect is now harmless',['The motion is void and the debate is erased','The chair must reopen nominations before voting','The vote must be taken by ballot to be valid'],'B','Once debate has begun or a vote is taken, lack of a second does not affect validity, since more than one member clearly wanted it discussed.',RONR),
  q(MOT,'Which class of motions deals with urgent matters unrelated to pending business, such as recessing?','Privileged motions',['Incidental motions','Subsidiary motions','Restorative motions'],'C','Privileged motions—recess, adjourn, fix the time to adjourn, raise a question of privilege and call for the orders of the day—are highest in rank.',BRIEF),
  q(MOT,'Which class of motions helps the assembly treat or dispose of a pending main motion?','Subsidiary motions',['Privileged motions','Incidental main motions','Motions that bring back'],'D','Subsidiary motions such as amend, refer, postpone and previous question apply to another motion and help the assembly dispose of it.',BRIEF),
  q(DEB,'Under Robert’s Rules, how long may each speech in debate last unless the assembly has other rules?','10 minutes',['5 minutes','15 minutes','No limit'],'A','In an ordinary assembly each member may speak twice per question per day, and each speech is limited to 10 minutes unless rules say otherwise.',RONR),
  q(DEB,'Which motion changes the number or length of speeches allowed in debate?','Limit or extend limits of debate',['Postpone to a certain time','Commit or refer to committee','Lay the question on the table'],'B','The motion to limit or extend limits of debate changes the normal rules of debate and needs a two-thirds vote because it affects members’ rights.',BRIEF),
  q(DEB,'A member wants to stop debate and vote immediately on the pending motion. What is the correct wording?','“I move the previous question.”',['“I call for the question.”','“I move to close the meeting.”','“I object to more debate.”'],'C','“Call the question” is not a motion; a member must obtain the floor and move the previous question, which needs a second and a two-thirds vote.',BRIEF),
  q(DEB,'During debate, a member begins attacking another member’s motives. What should the chair do?','Call the member to order and return debate to the issue',['Allow it, since debate on main motions is unlimited','Close debate and immediately put the vote','Ask the secretary to remove the member at once'],'D','Debate must be confined to the merits of the pending question. Speakers may condemn a measure but must never attack the motives of a member.',RONR),
  q(AMD,'A member moves to “insert the word ‘annual’ before ‘banquet’.” What form of amendment is this?','Inserting words',['Striking out words','Substituting a paragraph','Dividing the question'],'A','The basic processes of amendment are inserting or adding, striking out, and striking out and inserting; substituting is a form of the last.',RONR),
  q(AMD,'An amendment would change “buy a microscope” to “do not buy a microscope.” How should the chair rule?','Out of order, because it only creates a negative',['In order, because the amendment is germane','In order as long as it receives a second','Out of order, because amendments need notice'],'B','An amendment that merely turns an affirmative motion into its negative is improper, since voting no on the original achieves the same result.',RONR),
  q(AMD,'Which vote does a primary amendment to a main motion normally require?','A majority vote',['A two-thirds vote','Unanimous consent','A majority of the membership'],'C','Amendments to a main motion need a majority vote even if the main motion itself requires a higher vote to be adopted.',BRIEF),
  q(AMD,'A member wants to replace an entire pending resolution with a new one. Which motion is used?','Substitute (strike out and insert)',['Divide the question into parts','Reconsider the vote on the motion','Amend something previously adopted'],'D','A substitute replaces a whole paragraph or resolution. Members may first perfect both the original and the substitute before voting on it.',RONR),
  q(POST,'What is the effect of adopting the motion to postpone indefinitely?','The main motion is killed for that session',['The main motion is sent to a committee','The main motion is delayed to the next meeting','The main motion is laid aside temporarily'],'A','Postpone indefinitely kills the main motion without a direct vote. It is debatable and opens the main motion itself to debate as well.',BRIEF),
  q(POST,'A motion postponed to a certain time is taken up at that time as what?','A general order',['A special order','A new main motion','An incidental motion'],'B','A postponed motion becomes a general order for that time unless it is made a special order, which requires a two-thirds vote.',RONR),
  q(POST,'When moving to refer a motion to a committee, which details may the motion include?','The committee, how it is chosen and instructions',['The final vote the assembly must later take','The penalty for a late committee report','The number of times members may object'],'C','The motion to commit may specify which committee, how members are chosen, when to report and any instructions the assembly wants to give.',BRIEF),
  q(POST,'What vote does the motion to postpone to a certain time require?','A majority vote',['A two-thirds vote','Unanimous consent','A majority of the membership'],'D','Postponing to a certain time needs a majority vote; making it a special order for that time needs two-thirds because it can set aside other business.',BRIEF),
  q(MIND,'When must the motion to reconsider be made in a one-day meeting?','On the same day the vote was taken',['Within thirty days of the original vote','At the next regular meeting only','Any time before the minutes are approved'],'A','Reconsider must be made on the same day the vote was taken (or the next day in a multi-day session) by a member who voted on the prevailing side.',RONR),
  q(MIND,'What vote is needed to rescind an action if previous notice was given?','A majority vote',['A two-thirds vote','Unanimous consent','A majority of the board'],'B','Rescind needs a two-thirds vote, a majority with previous notice, or a majority of the entire membership. Notice lowers the required vote.',BRIEF),
  q(MIND,'Which action cannot be rescinded once it has been carried out?','A contract that has been signed and partly performed',['A main motion adopted at the last meeting','A standing rule adopted earlier that same day','A bylaw amendment adopted with previous notice'],'C','Rescind cannot undo actions carried out in a way that cannot be reversed, such as an executed contract or an elected member already notified.',RONR),
  q(MIND,'What vote is needed to adopt the motion to reconsider?','A majority, even if the original needed two-thirds',['A two-thirds vote in every single case','The same vote the original motion required','Unanimous consent of the members present'],'D','Reconsider needs only a majority. If adopted, the original motion returns to the floor exactly as it was just before the vote was taken.',RONR),
  q(VOTE,'With 50 members present, 30 vote yes, 15 vote no and 5 abstain. What is the result on a majority motion?','Adopted, because yes outnumbers no',['Lost, because 30 is not a majority of 50','Lost, because abstentions count as no','Adopted only if the chair also agrees'],'A','A majority is more than half of the votes cast. Abstentions are not votes cast, so 30 of 45 votes is a majority and the motion carries.',RONR),
  q(VOTE,'A motion needs a two-thirds vote. The count is 40 yes and 21 no. What is the result?','Lost, because 41 yes votes were needed',['Adopted, because yes is nearly double no','Adopted, because 40 is more than 30','Lost, because 21 members objected'],'B','Two-thirds of 61 votes cast is about 40.67, so 41 yes votes were needed. Yes votes must be at least twice the number of no votes.',RONR),
  q(VOTE,'When may the presiding officer of a large assembly vote?','When it would change the result, or by ballot',['On every motion, just like other members','Only when the bylaws are being amended','Never, under any circumstances at all'],'C','The chair, if a member, may vote when it affects the result—such as to make or break a tie—and always may vote on a ballot.',BRIEF),
  q(VOTE,'In a ballot election, a ballot names an eligible person who was not nominated. How is it treated?','It is counted as a legal vote for that person',['It is thrown out as an illegal ballot','It is added to the leading nominee’s votes','It is recorded as an abstention only'],'D','Write-in votes for eligible persons are legal unless the bylaws forbid them. Blank ballots are ignored and are not counted as votes cast.',RONR),
  q(VOTE,'Which voting method is used when the chair is unsure of a voice vote result?','A rising vote',['A roll call','A mail ballot','A proxy vote'],'A','If a voice vote is unclear, the chair may retake it as a rising vote, and may have it counted when needed for an accurate result.',BRIEF),
  q(BYL,'Which item usually belongs in the bylaws rather than in standing rules?','Qualifications and rights of members',['The time each meeting begins','Parking arrangements for meetings','Badge colors used at conferences'],'B','Bylaws contain the fundamental rules: name, membership, officers, meetings, executive board, committees, parliamentary authority and amendment.',BRIEF),
  q(BYL,'How do special rules of order differ from standing rules?','They govern meeting procedure and need two-thirds',['They deal only with dues and fees','They can be adopted by any single officer','They rank above the organization’s bylaws'],'C','Special rules of order modify the parliamentary authority’s procedures and need previous notice and two-thirds, or a majority of the membership.',RONR),
  q(BYL,'A bylaw amendment with notice would raise dues from $10 to $15. A member moves to make it $20. How should the chair rule?','Out of order, since it exceeds the scope of notice',['In order, since amendments are always allowed','In order if it is seconded by two members','Out of order, since dues can never be changed'],'D','Amendments to a pending bylaw change cannot exceed the scope of the notice, which protects members who stayed away relying on that notice.',RONR),
  q(BYL,'Which rule ranks lowest in an organization’s hierarchy of rules?','Standing rules',['Bylaws','Special rules of order','Corporate charter'],'A','The order of authority is: law, corporate charter, bylaws, special rules of order, parliamentary authority, then standing rules and customs.',BRIEF),
  q(ENF,'An action was taken that violates the bylaws, and no one objected at the time. What is its status?','It is null and void and may be challenged later',['It stands because no point of order was raised','It stands because a majority approved it','It automatically becomes a standing rule'],'B','A point of order is normally needed promptly, but actions that violate the bylaws or basic rights are null and void and can be challenged at any time.',RONR),
  q(ENF,'Which form is used to ask the chair how to proceed under the rules?','Parliamentary inquiry',['Point of order','Appeal from the chair','Question of privilege'],'C','A parliamentary inquiry asks the chair’s opinion on procedure. It is not a ruling, so the chair’s answer to an inquiry cannot be appealed.',BRIEF),
  q(ENF,'An appeal from the chair’s ruling ends in a tie vote. What is the result?','The chair’s ruling is sustained',['The chair’s ruling is overturned','The appeal is taken again by ballot','The parliamentarian decides the question'],'D','The question is “Shall the decision of the chair stand?” A majority in the negative is needed to overturn it, so a tie sustains the ruling.',RONR),
  q(ENF,'A member wants to address loud noise that keeps members from hearing. Which motion is used?','Raise a question of privilege',['Call for the orders of the day','Division of the assembly','Objection to consideration'],'A','A question of privilege deals with the rights, comfort or safety of the assembly or a member and can interrupt pending business if urgent.',BRIEF),
  q(TABLE,'Which of these motions is debatable?','Postpone to a certain time',['Previous question','Lay on the table','Suspend the rules'],'B','Postpone to a certain time is debatable, but only on the wisdom of postponing. Previous question, lay on the table and suspend the rules are not.',BRIEF),
  q(TABLE,'Which of these motions cannot be reconsidered?','Adjourn',['Amend','Commit','Rescind'],'C','Adjourn, recess and suspend the rules cannot be reconsidered because their effect is immediate or the same motion can simply be renewed later.',RONR),
  q(TABLE,'Which motion requires only a majority vote but cannot be amended or debated?','Lay on the table',['Commit or refer','Postpone indefinitely','Amend the main motion'],'D','Lay on the table is undebatable and unamendable yet needs only a majority, which is why it must never be used to kill a motion.',BRIEF),
  q(TABLE,'Which motion takes precedence over all others?','Fix the time to which to adjourn',['Recess for a set period','Raise a question of privilege','Call for the orders of the day'],'A','Fix the time to which to adjourn is the highest-ranking privileged motion, ranking above adjourn, recess, question of privilege and orders of the day.',RONR),
  q(TABLE,'Which of these requires a second?','Appeal from the decision of the chair',['Point of order on a rule violation','Parliamentary inquiry to the chair','Call for the orders of the day'],'B','An appeal needs a second because it asks the assembly to decide; a point of order, an inquiry and orders of the day do not need a second.',BRIEF),
  q(OFF,'What is the main duty of a parliamentarian?','To advise the presiding officer on procedure',['To rule on all points of order raised','To cast the deciding vote in ties','To preside whenever the president leaves'],'C','The parliamentarian is a consultant who gives advice. Only the chair rules, and the assembly may overrule the chair on appeal.',RONR),
  q(OFF,'The president wishes to debate a pending motion. What should they do?','Turn the chair over to the vice-president',['Debate from the chair as any member would','Ask the secretary to read their remarks','Speak only after the vote is taken'],'D','The president relinquishes the chair until the pending main question is disposed of, so that the meeting remains impartial.',BRIEF),
  q(OFF,'In a small board of not more than about twelve members, which rule differs from a large assembly?','The chair may debate and make motions',['Motions must always be seconded','Speeches are limited to five minutes','All votes must be taken by ballot'],'A','In small boards and committees, motions need no second, members may speak more often, and the chair may take part in debate and vote.',RONR),
  q(OFF,'How does a committee bring its recommendations before the assembly?','The reporting member moves their adoption',['The president adopts them without a vote','They are placed on file and not discussed','The secretary votes on them for the group'],'B','When a committee report contains recommendations, the reporting member usually moves their adoption, and no second is required.',RONR)
 ],3826)
};
